window.MGProseData("12034f1b37f1bd653683999ad049abcd60c0c5e27ea8d36d3df98dd0f1c1fd6d",{"html":"\u003cp>记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>r\u003c/mi>\u003c/munderover>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>h\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>4.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nT=\\sum_{i=1}^r\\binom{n_i}{2},\\qquad h=T+d,\\qquad\nq_F=2,\\quad q_{K_{-1}}=q_{K_2}=4.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L=|\\mathcal O_L/2\\mathcal O_L|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，不是剩余域的大小。\u003c/p>\n\u003cp>对每个块定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmtext>否则\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\kappa_i(A)=\n\\sum_{\\substack{a\\in I_i\\\\ b\\notin I_i}}\n\\frac{(A_i)_{ba}}2\\pmod2\\in\\mathbb F_2,\n\\qquad\n\\eta(A)=\n\\begin{cases}\n1,\u0026amp;\\kappa_i(A)=0\\quad(\\forall i),\\\\\n0,\u0026amp;\\text{否则}.\n\\end{cases}\n\\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这些量只需 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 即可计算。\u003c/p>\n\u003cp>三个域上的可行性判准完全相同：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\mathscr S_L(A)\\ne\\varnothing\\iff\\eta(A)=1.}\n\\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n全部基数如下，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>T\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(3)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{|\\mathscr R_{L,M}(A)|=\\eta(A)\\,2^r q_L^{(M-1)T}.}\n\\tag{3}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>h\u003c/mi>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(4)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n|\\mathscr C_{L,M}(A)|=\n\\begin{cases}\nq_L^{h},\u0026amp;M=2,\\\\\n\\eta(A)\\,2^r q_L^{(M-1)T+d},\u0026amp;M\\ge3.\n\\end{cases}}\n\\tag{4}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,2}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 总非空；其余集合的非空条件就是 (2)。\u003c/p>\n\u003cp>还有一个直接可核验的提升判准。给定\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar U\\in\\mathscr C_{L,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，任取其整系数提升\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widetilde U=(\\widetilde u_1,\\ldots,\\widetilde u_d)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsubsup>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(5)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\bar U\\in\\mathscr R_{L,M}(A)\n\\iff\n\\widetilde u_a^{\\mathsf T}\\widetilde u_a\n\\equiv1\\pmod{2^{M+1}\\mathcal O_L}\n\\quad(1\\le a\\le d).\n}\n\\tag{5}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n右侧与所选提升无关：改变一列 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其范数改变\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsubsup>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmi>v\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\\widetilde u_a^{\\mathsf T}v+2^{2M}v^{\\mathsf T}v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>先证明这些结论，并计算一般约化映射的纤维。\u003c/p>\n\u003cp>对矩阵迭代多项式 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x)=3x^2-2x^3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>x\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmi>x\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf(x)-x=-(2x-1)(x^2-x),\\qquad\nf(x)^2-f(x)=-(x^2-x)^2(3-2x)(2x+1),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 出发的迭代收敛到一个对称幂等矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nP_i\\equiv E_i\\pmod2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i,A_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 彼此交换。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\\ne j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_iP_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为零的幂等矩阵，故为零；同理\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>i\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(6)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nP_iP_j=0\\ (i\\ne j),\\qquad \\sum_iP_i=I.\n\\tag{6}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里用了简单事实：若幂等矩阵属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2M_d(\\mathbb Z_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则反复平方表明它属于每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^mM_d(\\mathbb Z_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，因而为零。\u003c/p>\n\u003cp>取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">im\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{im}P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的图形基 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使其在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 行上的子矩阵为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I_{n_i}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi>I\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>S\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsubsup>\u003cmi>S\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>S\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(7)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nB_i=\n\\begin{pmatrix}\nI_{n_i}\\\\ 2S_i\n\\end{pmatrix},\n\\qquad\nG_i:=B_i^{\\mathsf T}B_i=I_{n_i}+4S_i^{\\mathsf T}S_i,\n\\tag{7}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中行的排列按 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与其补集理解。令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=(B_1,\\ldots,B_r)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsup>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(8)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nB\\equiv I\\pmod2,\\qquad\nB^{\\mathsf T}B=\\operatorname{diag}(G_1,\\ldots,G_r).\n\\tag{8}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i^2=P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可知 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(P_i)_{I_i,I_i}\\equiv I\\pmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。再将\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[A_i,P_i]=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 展开，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>S\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n(S_i)_{ba}\\equiv \\frac{(A_i)_{ba}}2\\pmod2\n\\quad(a\\in I_i,\\ b\\notin I_i).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">tr\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsubsup>\u003cmi>S\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>S\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(9)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{tr}(S_i^{\\mathsf T}S_i)\\equiv\\kappa_i(A)\\pmod2.\n\\tag{9}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>这个分解也适用于有限精度。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足题中的正交与同时分块条件，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U^{-1}A_iU\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 块对角，因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U^{-1}P_iU\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也块对角。后者是模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的幂等矩阵，只能等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。在有限商环中，同一论证使用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的幂零性成立。因此，真解及形式解都分别对应于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>B\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsubsup>\u003cmi>Q\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(10)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nU=B\\,\\operatorname{diag}(Q_1,\\ldots,Q_r),\\qquad\nQ_i\\equiv I\\pmod2,\\qquad\nQ_i^{\\mathsf T}G_iQ_i=I,\n\\tag{10}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n最后一个等式按相应精度理解。\u003c/p>\n\u003cp>下面使用一个提升引理。设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对称，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>Q\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>G\u003c/mi>\u003cmi>Q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q^{\\mathsf T}GQ\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的非对角元属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^m\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，对角元模\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{m+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。则存在\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>Q\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsubsup>\u003cmi>Q\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmi>G\u003c/mi>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(11)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nQ_\\infty\\equiv Q\\pmod{2^m},\\qquad Q_\\infty^{\\mathsf T}GQ_\\infty=I.\n\\tag{11}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n事实上，右乘 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I+2^mZ\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后，下一位非对角误差由\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z_{ab}+Z_{ba}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 控制，下一位对角误差由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z_{aa}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 控制，均在\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_L/2\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中独立可解。具体地，若当前 Gram 矩阵为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left right left\" columnspacing=\"0em 1em 0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi mathvariant=\"normal\">n\u003c/mi>\u003cmi mathvariant=\"normal\">e\u003c/mi>\u003cmi mathvariant=\"normal\">w\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi mathvariant=\"normal\">n\u003c/mi>\u003cmi mathvariant=\"normal\">e\u003c/mi>\u003cmi mathvariant=\"normal\">w\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n(H_{\\rm new})_{ab}\n\u0026amp;\\equiv H_{ab}+2^m(Z_{ab}+Z_{ba})\\pmod{2^{m+1}}\n\u0026amp;\u0026amp; (a\\ne b),\\\\\n(H_{\\rm new})_{aa}\n\u0026amp;\\equiv H_{aa}+2^{m+1}Z_{aa}\\pmod{2^{m+2}}.\n\\end{aligned}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n逐层进行并利用完备性，即得 (11)。结合 (10)，这也证明了 (5)。\u003c/p>\n\u003cp>现在考虑一个块 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G=I+4D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>S\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D=S^{\\mathsf T}S\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\\equiv I\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>Q\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>G\u003c/mi>\u003cmi>Q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q^{\\mathsf T}GQ=I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，写\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>Q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det Q=1+2z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取行列式并模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">tr\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>于 \u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(12)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{tr}D+z+z^2=0\n\\quad\\text{于 }\\mathcal O_L/2\\mathcal O_L.\n\\tag{12}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n三个环的剩余域都是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>z\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z+z^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在剩余域中为零，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">tr\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{tr}D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 必须为偶数。\u003c/p>\n\u003cp>反过来，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">tr\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{tr}D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为偶数，则存在一个对称零对角矩阵\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\in M_n(\\mathbb F_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(13)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\sum_{b\\ne a}X_{ba}=D_{aa}\\pmod2.\n\\tag{13}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这是因为完全图的边界映射的像恰为坐标和为零的向量空间；也可直接用以第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个顶点为中心的星形图构造。取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的整数提升，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q_0=I+2X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>Q\u003c/mi>\u003cmn>0\u003c/mn>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmi>G\u003c/mi>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q_0^{\\mathsf T}GQ_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的非对角元被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 整除，对角元模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 (11)，它可在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上提升为真正的等距矩阵。\u003c/p>\n\u003cp>这证明了 (2)，并给出构造基域真解 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的方法。一旦可行，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmunderover>\u003cmo>∏\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>r\u003c/mi>\u003c/munderover>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>g\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>O\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>g\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(14)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\mathscr S_L(A)=\nU_0\\prod_{i=1}^r\n\\{g\\in O_{n_i}(\\mathcal O_L):g\\equiv I\\pmod2\\}.\n\\tag{14}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>为计数，先看一个秩 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的标准块，记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=\\binom n2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的形式解是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I+2X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Sym\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX\\in\\operatorname{Sym}_n(\\mathcal O_L/2\\mathcal O_L).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它可真正提升，当且仅当\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>b\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(15)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nX_{aa}+\\sum_bX_{ba}^2=0\n\\quad(\\forall a).\n\\tag{15}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在基域上，这要求非对角部分的每个顶点度数为偶数，对角元任意，故共有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{t+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个。\u003c/p>\n\u003cp>在两个扩域上，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>ϵ\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>ϵ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathcal O_\\mu/2\\mathcal O_\\mu\n\\simeq\\mathbb F_2[\\epsilon]/(\\epsilon^2),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时可取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ϵ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\epsilon=\\theta_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时可取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ϵ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\epsilon=1+\\theta_{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。写 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>ϵ\u003c/mi>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X=A+\\epsilon B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 (15) 等价于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nB_{aa}=0,\\qquad \\sum_{b\\ne a}A_{ba}=0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此共有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{2t+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个。两种情形统一写成 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2q_L^t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>从精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 提升到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取一个真正代表 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其上方的矩阵写为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmi>X\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng(I+2^mX)\\pmod{2^{m+1}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n成为形式解等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对称；成为真正解的约化类还要求\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{diag}X=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。故每块的两种纤维大小分别为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^{t+n}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。同时，(5) 表明下一层形式解必落入当前层真正可提升的集合。于是，对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有下表：\u003c/p>\n\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>约化映射\u003c/th>\n\u003cth>约化像\u003c/th>\n\u003cth style=\"text-align:right\">每个非空纤维的大小\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M+1}\\to\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:right\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>T\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^T\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,M+1}\\to\\mathscr C_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:right\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>h\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003c/tbody>\n\u003c/table>\n\u003cp>若该像为空，则源也为空。模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，(8) 给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>h\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\mathscr C_{L,2}|=q_L^h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；结合上述首层真解计数与纤维计算，即得 (3)、(4)。\u003c/p>\n\u003cp>现在讨论伽罗瓦固定点。令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"fraktur\">s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∏\u003c/mo>\u003cmi>i\u003c/mi>\u003c/munder>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Sym\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"fraktur\">a\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>B\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"fraktur\">s\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathfrak s=\\prod_i\\operatorname{Sym}_{n_i}(\\mathbb F_2),\\qquad\n\\mathfrak a=\\{B\\in\\mathfrak s:\\operatorname{diag}B=0\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n把它们视为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>d\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>d\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d\\times d\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 块对角矩阵空间，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>dim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi mathvariant=\"fraktur\">s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>dim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi mathvariant=\"fraktur\">a\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>T\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\dim\\mathfrak s=h,\\qquad \\dim\\mathfrak a=T.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n以下相加都在模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的矩阵环中进行。\u003c/p>\n\u003ch1>对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，形式解的固定类都有唯一表达\n[\n\\boxed{\n\\mathscr C_{K_\\mu,M}(A)^{\\sigma_\\mu}\u003c/h1>\n\u003ch1>{V+2^{M-1}\\theta_\\mu B:\nV\\in\\mathscr C_{F,M}(A),\\ B\\in\\mathfrak s}.\n}\n\\tag{16}\n]\n对真正解的约化类，当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\n[\n\\boxed{\n\\mathscr R_{K_\\mu,M}(A)^{\\sigma_\\mu}\u003c/h1>\n\u003cp>{V+2^{M-1}\\theta_\\mu B:\nV\\in\\mathscr R_{F,M}(A),\\ B\\in\\mathfrak a}.\n}\n\\tag{17}\n]\u003c/p>\n\u003ch1>模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的答案需要单独写出。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\in\\mathscr C_{F,2}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmsubsup>\u003cmover accent=\"true\">\u003cmi>v\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>v\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(18)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nc_a(V)=\\frac{\\widetilde v_a^{\\mathsf T}\\widetilde v_a-1}{4}\\pmod2,\n\\tag{18}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>V\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widetilde V\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是任意整数提升。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"fraktur\">a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\\in\\mathfrak a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>B\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/munder>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n(\\partial B)_a=\\sum_{\\substack{b\\in I_i\\\\b\\ne a}}B_{ba},\n\\qquad a\\in I_i.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则\n[\n\\boxed{\n\\mathscr R_{K_\\mu,2}(A)^{\\sigma_\\mu}\u003c/h1>\n\u003cp>{V+2\\theta_\\mu B:\nV\\in\\mathscr C_{F,2}(A),\u003cbr>\nB\\in\\mathfrak a,\u003cbr>\nc(V)=\\bar\\mu,\\partial B}.\n}\n\\tag{19}\n]\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>μ\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu\\bmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。特别地：\u003c/p>\n\u003cul>\n\u003cli>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，(17) 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时也成立。\u003c/li>\n\u003cli>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，条件是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c(V)=\\partial B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 未必属于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,2}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>两个扩域上都有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{K_\\mu,2}^{\\sigma_\\mu}=\\mathscr R_{K_\\mu,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{K_\\mu,2}^{\\sigma_\\mu}=\\mathscr C_{K_\\mu,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ul>\n\u003cp>证明这些公式只需展开。固定标量类恰为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>b\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\na+2^{M-1}\\theta_\\mu b,\n\\qquad a\\in\\mathbb Z/2^M,\\quad b\\in\\mathbb F_2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此固定矩阵类唯一写作 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V+2^{M-1}\\theta_\\mu B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。将正交条件模\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 展开，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 正交且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对称；将同时分块条件展开，利用\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\\equiv E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\equiv I\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 必须块对角。这证明 (16)。\u003c/p>\n\u003ch1>对一列，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>δ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\delta=2^{M-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n[\n(v+\\delta\\theta_\\mu b)^{\\mathsf T}(v+\\delta\\theta_\\mu b)-1\u003c/h1>\n\u003cp>v^{\\mathsf T}v-1\n+2^M\\theta_\\mu v^{\\mathsf T}b\n+2^{2M-2}\\mu,b^{\\mathsf T}b.\n\\tag{20}\n]\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，最后一项模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 消失。由 (5)，其余两项分别给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\in\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{diag}B=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即 (17)。\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，(20) 则给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmi>μ\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>b\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nB_{aa}=0,\\qquad c_a(V)=\\bar\\mu\\sum_bB_{ba},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n即 (19)。\u003c/p>\n\u003cp>特别地，扩域不会产生新的、条目全在基域商环中的真正可提升类：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∩\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(21)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\mathscr R_{K_\\mu,M}(A)\\cap\nM_d(\\mathbb Z_2/2^M\\mathbb Z_2)\n=\\mathscr R_{F,M}(A).\n}\n\\tag{21}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n形式解也有对应的交集等式。对真正解本身则有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(22)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\mathscr S_{K_\\mu}(A)^{\\sigma_\\mu}=\\mathscr S_F(A).}\n\\tag{22}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch1>固定点数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>M\u003c/mi>\u003cmi>T\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(23)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n|\\mathscr R_{K_\\mu,M}^{\\sigma_\\mu}|\n=\\eta(A)\\,2^{r+MT}\\qquad(M\\ge2),\n}\n\\tag{23}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n[\n\\boxed{\n|\\mathscr C_{K_\\mu,M}^{\\sigma_\\mu}|\u003c/h1>\n\u003cp>\\begin{cases}\n2^{2h},\u0026amp;M=2,\\\n\\eta(A),2^{r+MT+2d},\u0026amp;M\\ge3.\n\\end{cases}}\n\\tag{24}\n]\n式 (23) 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时由所有类均固定得到，在其余精度由 (17) 得到。\u003c/p>\n\u003cp>当集合非空时，固定真解类与基域真解类的数量比为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>T\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^T\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；固定形式解类与基域形式解类的数量比为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>h\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此前者在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时相等，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时严格扩大；后者只要非空，就严格扩大。\u003c/p>\n\u003ch1>由二阶群作用的 Burnside 公式，轨道数为\n[\n\\boxed{\n#\\bigl(\\mathscr R_{K_\\mu,M}/\\langle\\sigma_\\mu\\rangle\\bigr)\u003c/h1>\n\u003ch1>\\eta(A),2^{r-1}\n\\left(2^{2(M-1)T}+2^{MT}\\right).\n}\n\\tag{25}\n]\n[\n\\boxed{\n#\\bigl(\\mathscr C_{K_\\mu,M}/\\langle\\sigma_\\mu\\rangle\\bigr)\u003c/h1>\n\u003cp>\\begin{cases}\n2^{2h},\u0026amp;M=2,\\\n\\eta(A),2^{r+2d-1}\n\\left(2^{2(M-1)T}+2^{MT}\\right),\u0026amp;M\\ge3.\n\\end{cases}}\n\\tag{26}\n]\u003c/p>\n\u003cp>固定点集之间的约化映射如下，对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均成立：\u003c/p>\n\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>约化映射\u003c/th>\n\u003cth>约化像\u003c/th>\n\u003cth style=\"text-align:right\">每个非空纤维的大小\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{K_\\mu,M+1}^{\\sigma_\\mu}\\to\\mathscr R_{K_\\mu,M}^{\\sigma_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:right\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>4\u003c/mn>\u003cmi>T\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4^T\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{K_\\mu,M+1}^{\\sigma_\\mu}\\to\\mathscr C_{K_\\mu,M}^{\\sigma_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:right\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>4\u003c/mn>\u003cmi>h\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4^h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003c/tbody>\n\u003c/table>\n\u003cp>因为源精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M+1\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可以使用 (16)、(17)：其中的\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\\theta_\\mu B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 项约化后消失，而基域部分的约化像由前一张表给出。\n两种纤维大小分别是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>T\u003c/mi>\u003c/msup>\u003cmo>⋅\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>4\u003c/mn>\u003cmi>T\u003c/mi>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>h\u003c/mi>\u003c/msup>\u003cmo>⋅\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>h\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>4\u003c/mn>\u003cmi>h\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^T\\cdot2^T=4^T,\\qquad 2^h\\cdot2^h=4^h.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>这也完全回答了固定类的提升与相容性问题。对任一固定矩阵类，以下条件等价：\u003c/p>\n\u003col>\n\u003cli>它可提升为一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-固定的真正解；\u003c/li>\n\u003cli>它可成为一条在所有更高精度上逐层相容的固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-类序列的分量；\u003c/li>\n\u003cli>它可成为一条在所有更高精度上逐层相容的固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-类序列的分量；\u003c/li>\n\u003cli>它属于嵌入的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ol>\n\u003cp>事实上，连“存在下一层固定类提升”就已等价于这些条件。具体而言：\u003c/p>\n\u003cul>\n\u003cli>对固定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-类，条件就是其条目均来自\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb Z_2/2^M\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即上述唯一表达中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>对固定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-类，还需其基域部分满足 (5)。\u003c/li>\n\u003c/ul>\n\u003cp>最后，第三问中的最大整数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>即所有 \u003c/mtext>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(27)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\nN_{\\max}=\n\\begin{cases}\nM,\u0026amp;T=0\\quad\\text{即所有 }n_i=1,\\\\\nM-1,\u0026amp;T\u0026gt;0.\n\\end{cases}}\n\\tag{27}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>先证明下界。给定题设中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类是固定的\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-类。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由固定点约化像的结论，它模\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 落在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M-1}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故存在所需的\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\\in\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由可行性等价知基域真解存在，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>W\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U,W\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以仍能取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N=M-1=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>若所有块秩均为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 (14) 中每个正交群只有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{1,-1\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以更强地有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(28)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\mathscr S_{K_\\mu}(A)=\\mathscr S_F(A).}\n\\tag{28}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这给出精确下降。\u003c/p>\n\u003cp>对给定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A,U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，写其唯一展开为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>X\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nU=X+\\theta_\\mu Y,\\qquad X,Y\\in M_d(\\mathbb Z_2).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n能够取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N=M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的必要充分条件是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>U\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>U\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(29)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\nY\\equiv0\\pmod{2^M}\n\\iff\n\\sigma_\\mu(U)\\equiv U\\pmod{2^{M+1}\\mathcal O_\\mu}.\n}\n\\tag{29}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n必要性显然；充分性由 (21) 得到。第二个等价关系来自\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>U\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma_\\mu(U)-U=-2\\theta_\\mu Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 以及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{1,\\theta_\\mu\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-基性质。\u003c/p>\n\u003cp>下面给出反例和统一构造，验证所有上述严格性及界的最优性。\u003c/p>\n\u003cp>首先，只要 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，选不同块中的坐标 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p\\in I_i,q\\in I_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>J\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>p\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi>e\u003c/mi>\u003cmi>q\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi>e\u003c/mi>\u003cmi>p\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>J\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>J\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(30)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nJ=e_pe_q^{\\mathsf T}+e_qe_p^{\\mathsf T},\\qquad\nA_i=E_i+2J,\\quad A_j=E_j-2J,\\quad A_k=E_k\\ (k\\ne i,j).\n\\tag{30}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这些矩阵对称且交换：在所选二维空间上，后两个非平凡矩阵互为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 减去对方。此时\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>κ\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\kappa_i=\\kappa_j=1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故三个域上均无真解，精度至少为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时也无形式解。但是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>J\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nI+2J\\pmod4\\in\\mathscr C_{L,2}(A).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这给出了模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可解而实际不可解的例子，也说明两个二次扩张都不能消除可行性障碍。\u003c/p>\n\u003cp>其次，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，把某个对角元改为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1+2^{M-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、其余保持为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到基域形式解，但\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≢\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n(1+2^{M-1})^2\\not\\equiv1\\pmod{2^{M+1}},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故它不属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，只要某块秩至少为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，块内矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>J\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I+2J\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也给出这样的例子，其相应列范数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>5\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">5\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n若所有块秩均为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则确实有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{F,2}=\\mathscr R_{F,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>在扩域上，对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，把某个对角元改为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(31)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n1+2^{M-1}\\theta_\\mu\n\\tag{31}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n即可得到固定的形式解。其范数误差为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi>μ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^M\\theta_\\mu+2^{2M-2}\\mu,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n不被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 整除。因此它不是可提升真解类，也不能处于无限相容的固定类序列中。这是适用于任意精度、任意块秩的统一例子。\u003c/p>\n\u003cp>最后，设某块秩至少为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，仍取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在该块选取二维平面。令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>τ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>τ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>τ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\tau_2=\\theta_2,\\qquad \\tau_{-1}=1+\\theta_{-1},\\qquad\nz=2^{M-2}\\tau_\\mu,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并在该平面上置\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmi>c\u003c/mi>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmi>s\u003c/mi>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmi>c\u003c/mi>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>c\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>z\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(32)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nR(z)=\n\\begin{pmatrix}\nc\u0026amp;s\\\\-s\u0026amp;c\n\\end{pmatrix},\n\\qquad\nc=\\frac{1-z^2}{1+z^2},\\quad\ns=\\frac{2z}{1+z^2}.\n\\tag{32}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在其余坐标上取恒等矩阵。\u003c/p>\n\u003cp>因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z^2\\in2\\mathcal O_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，分母为单位；又\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>c\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>s\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c^2+s^2=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R(z)\\equiv I\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故得到真正的扩域解。\u003c/p>\n\u003cp>当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ns=\\frac{2^{M-1}\\theta_2}{1+2^{2M-3}},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 系数恰有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-进赋值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在基域中。\u003c/p>\n\u003cp>当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lambda=2^{2M-3}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsup>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>λ\u003c/mi>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nc=\\frac{1-\\lambda^2-2\\lambda\\theta_{-1}}{1+\\lambda^2},\n\\qquad\ns=\n\\frac{2^{M-1}\\bigl((1+\\lambda)+(1-\\lambda)\\theta_{-1}\\bigr)}\n{1+\\lambda^2}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta_{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 系数也恰有赋值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的该系数赋值为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>≥\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2M-2\\ge M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此，两个扩域上都满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≢\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(33)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\sigma_\\mu(R(z))\\equiv R(z)\\pmod{2^M},\n\\qquad\n\\sigma_\\mu(R(z))\\not\\equiv R(z)\\pmod{2^{M+1}}.\n\\tag{33}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 (29)，不存在基域真解与它模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 相同。这统一证明了所有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 界的最优性；这些类也都是不能提升为固定真解、不能继续提升为下一层固定类的固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-类。\u003c/p>\n\u003cp>在特殊的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=-1,M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 情形，(32) 给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmn>5\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmn>6\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmn>5\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nc=\\frac{-3-4\\theta_{-1}}5,\\qquad\ns=\\frac{6-2\\theta_{-1}}5,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\begin{pmatrix}\n1\u0026amp;2+2\\theta_{-1}\\\\\n2+2\\theta_{-1}\u0026amp;1\n\\end{pmatrix}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它的基域部分\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnspacing=\"0.2778em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left(\\begin{smallmatrix}1\u0026amp;2\\\\2\u0026amp;1\\end{smallmatrix}\\right)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n列范数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>5\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">5\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，不属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这具体展示了 (19) 中必须保留的例外。\u003c/p>\n\u003cp>对任意其他可行输入，把这些块内例子左乘基域真解 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即可得到对应输入上的同类例子。整个证明只使用了所给整数环的结构与完备性，无需援引二次型分类定理。\u003c/p>\n","source":"assets/content/12034f1b37f1bd653683999ad049abcd60c0c5e27ea8d36d3df98dd0f1c1fd6d.html"});
